        	this.world.playSoundEffect(this.posX, this.posY, this.posZ, "ambient.weather.thunder", 10000.0F, 0.8F + this.rand.nextFloat() * 0.2F);

        	if(waste || extType != 1) {
        		ExplosionNukeGeneric.dealDamage(this.world, this.posX, this.posY, this.posZ, this.destructionRange * 2);
        	} else {
        		ExplosionHurtUtil.doRadiation(this.world, posX, posY, posZ, 15000, 250000, this.destructionRange);
        	}

        } else {
			if (!did2 && waste) {
				EntityFalloutRain fallout = new EntityFalloutRain(this.world, (int)(this.destructionRange * 1.8) * 10);
				fallout.posX = this.posX;
				fallout.posY = this.posY;
				fallout.posZ = this.posZ;
				fallout.setScale((int)(this.destructionRange * 1.8));

				this.world.spawnEntityInWorld(fallout);
				//this.worldObj.getWorldInfo().setRaining(true);

				did2 = true;
			}
		}

		age++;
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		if(!this.world.isRemote) loadChunk((int) Math.floor(posX / 16D), (int) Math.floor(posZ / 16D));

		if(!this.did) {

			if(GeneralConfig.enableExtendedLogging && !this.world.isRemote)
				MainRegistry.logger.log(Level.INFO, "[NUKE] Initialized TOM explosion at " + posX + " / " + posY + " / " + posZ + " with strength " + destructionRange + "!");

			exp = new ExplosionTom((int) this.posX, (int) this.posY, (int) this.posZ, this.world, this.destructionRange);

			if(!this.world.isRemote) {
				CelestialBody body = CelestialBody.getBody(this.world);
				body.modifyTraits(new CBT_Impact(this.world.getTotalWorldTime()));
			}

			this.did = true;
		}

		speed += 1; // increase speed to keep up with expansion

		boolean flag = false;
		for(int i = 0; i < this.speed; i++) {
			flag = exp.update();

			if(flag) {
				this.setDead();
				TomSaveData data = TomSaveData.forWorld(this.world);
				data.impact = true;
				data.fire = 1F;
				data.markDirty();
			}
		}

		if(rand.nextInt(5) == 0)
			this.world.playSoundEffect(this.posX, this.posY, this.posZ, "random.explode", 10000.0F, 0.8F + this.rand.nextFloat() * 0.2F);

		if(!flag) {
			this.world.playSoundEffect(this.posX, this.posY, this.posZ, "ambient.weather.thunder", 10000.0F, 0.8F + this.rand.nextFloat() * 0.2F);
			ExplosionNukeGeneric.dealDamage(this.world, this.posX, this.posY, this.posZ, this.destructionRange * 2);
		}

		age++;
	}

