public void decompress(ThreeInts pos, ForgeDirection dir) {
		World world = handler.getWorld();

		EntityDepress depress = new EntityDepress(world, dir.getOpposite(), 20);
		depress.posX = pos.x + 0.5;
		depress.posY = pos.y + 0.5;
