@Override
	public boolean hitEntity(ItemStack stack, EntityLivingBase victim, EntityLivingBase attacker) {

		boolean active = stack.getItemDamage() < stack.getMaxDamage();

		if(active) {

			attacker.world.playSoundEffect(victim.posX, victim.posY, victim.posZ, "mob.zombie.woodbreak", 1.0F, 0.75F + victim.getRNG().nextFloat() * 0.2F);

			if(!attacker.world.isRemote && !victim.isEntityAlive()) {
				int count = Math.min((int)Math.ceil(victim.getMaxHealth() / 3D), 250);

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaburst");
				data.setInteger("count", count * 4);
				data.setDouble("motion", 0.1D);
				data.setString("mode", "blockdust");
				data.setInteger("block", Block.getIdFromBlock(Blocks.redstone_block));
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, victim.posX, victim.posY + victim.height * 0.5, victim.posZ), new TargetPoint(victim.dimension, victim.posX, victim.posY + victim.height * 0.5, victim.posZ, 50));
			}

			if(attacker instanceof EntityPlayer && (((EntityPlayer)attacker).getDisplayName().equals("Tankish") || ((EntityPlayer)attacker).getDisplayName().equals("Tankish020")))
				return true;

			return super.hitEntity(stack, victim, attacker);
		} else {

			if(!attacker.world.isRemote && attacker instanceof EntityPlayer)
				((EntityPlayer)attacker).sendMessage(new TextComponentString("Not enough energy.").setStyle(new Style().setColor(TextFormatting.RED)));
			return false;
		}
	}

public boolean onEntityItemUpdate(EntityItem item) {
		World world = item.world;

		if(item.ticksExisted > 50 * 20 || item.isBurning()) {

			if(!world.isRemote) {

				if(WeaponConfig.dropStar) {

					EntityNukeExplosionMK3 ex = EntityNukeExplosionMK3.statFacFleija(world, item.posX, item.posY, item.posZ, 100);
					if(!ex.isDead) {
						world.playSoundEffect(item.posX, item.posY, item.posZ, "random.explode", 100.0F, world.rand.nextFloat() * 0.1F + 0.9F);
						world.spawnEntityInWorld(ex);

						EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(world, 100);
						cloud.posX = item.posX;
						cloud.posY = item.posY;
						cloud.posZ = item.posZ;
						world.spawnEntityInWorld(cloud);
					}
				}

				item.setDead();
			}
		}

		int randy = (50 * 20) - item.ticksExisted;

		if(randy < 1)
			randy = 1;

		if(item.world.rand.nextInt(50 * 20) >= randy)
			world.spawnParticle("reddust", item.posX + item.world.rand.nextGaussian() * item.width / 2, item.posY + item.world.rand.nextGaussian() * item.height, item.posZ + item.world.rand.nextGaussian() * item.width / 2, 0.0, 0.0, 0.0);
		else
			world.spawnParticle("smoke", item.posX + item.world.rand.nextGaussian() * item.width / 2, item.posY + item.world.rand.nextGaussian() * item.height, item.posZ + item.world.rand.nextGaussian() * item.width / 2, 0.0, 0.0, 0.0);

		if(randy < 100)
			world.spawnParticle("lava", item.posX + item.world.rand.nextGaussian() * item.width / 2, item.posY + item.world.rand.nextGaussian() * item.height, item.posZ + item.world.rand.nextGaussian() * item.width / 2, 0.0, 0.0, 0.0);

		return false;
	}

public static void gib(EntityLivingBase entity) {
		if(entity instanceof EntityOcelot) return;

		int type = 0;
		if(entity instanceof EntitySlime) type = 1;
		if(entity instanceof EntityMagmaCube) type = 1;
		if(entity instanceof EntityCreeper) type = 1;
		if(entity instanceof EntityGolem) type = 2;
		if(entity instanceof EntityIronGolem) type = 2;
		if(entity instanceof EntityCyberCrab) type = 2;
		if(entity instanceof EntityTeslaCrab) type = 2;
		if(entity instanceof EntityTaintCrab) type = 2;
		if(entity instanceof EntityBlaze) type = 2;
		if(entity instanceof EntityFBIDrone) type = 2;
		if(entity instanceof EntityRADBeast) type = 2;
		if(entity instanceof EntityUFO) type = 2;
		if(entity instanceof EntityBOTPrimeBase) type = 2;

		SkeletonCreator.composeEffectGib(entity.world, entity, 0.25F);

		if(entity instanceof EntitySkeleton) return;

		NBTTagCompound vdat = new NBTTagCompound();
		vdat.setString("type", "giblets");
		vdat.setInteger("ent", entity.getEntityId());
		vdat.setInteger("gibType", type);
		PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, entity.posX, entity.posY + entity.height * 0.5, entity.posZ), new TargetPoint(entity.dimension, entity.posX, entity.posY + entity.height * 0.5, entity.posZ, 150));
		entity.world.playSoundEffect(entity.posX, entity.posY, entity.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + entity.getRNG().nextFloat() * 0.2F);
	}

