	public static BiConsumer<ItemStack, LambdaContext> ORCHESTRA_DRILL = (stack, ctx) -> {
		EntityLivingBase entity = ctx.entity;
		GunAnimation type = ItemGunBaseNT.getLastAnim(stack, ctx.configIndex);
		int timer = ItemGunBaseNT.getAnimTimer(stack, ctx.configIndex);

		if(entity.world.isRemote) {
			double speed = HbmAnimations.getRelevantTransformation("SPEED")[0];

			AudioWrapper runningAudio = ItemGunBaseNT.loopedSounds.get(entity);

			if(speed > 0) {
				//start sound
				if(runningAudio == null || !runningAudio.isPlaying()) {
					boolean electric = XWeaponModManager.hasUpgrade(stack, ctx.configIndex, XWeaponModManager.ID_ENGINE_ELECTRIC);
					AudioWrapper audio = MainRegistry.proxy.getLoopedSound(electric ? "hbm:block.largeTurbineRunning" : "hbm:block.engine", (float) entity.posX, (float) entity.posY, (float) entity.posZ, (float) speed, 15F, (float) speed, 25);
					ItemGunBaseNT.loopedSounds.put(entity, audio);
					audio.startSound();
					audio.attachTo(entity);
				}
				//keepalive
				if(runningAudio != null && runningAudio.isPlaying()) {
					runningAudio.keepAlive();
					runningAudio.updateVolume((float) speed);
					runningAudio.updatePitch((float) speed);
				}
			} else {
				//stop sound due to timeout
				//if(runningAudio != null && runningAudio.isPlaying()) runningAudio.stopSound();
				// for some reason this causes stutters, even though speed shouldn't be 0 then
			}
		}
		//stop sound due to state change
		if(type != GunAnimation.CYCLE && type != GunAnimation.CYCLE_DRY && entity.world.isRemote) {
			AudioWrapper runningAudio = ItemGunBaseNT.loopedSounds.get(entity);
			if(runningAudio != null && runningAudio.isPlaying()) runningAudio.stopSound();
		}
		if(entity.world.isRemote) return;

		if(type == GunAnimation.RELOAD) {
			if(timer == 15) entity.world.playSoundAtEntity(entity, "hbm:weapon.reload.openLatch", 1F, 1F);
			if(timer == 35) entity.world.playSoundAtEntity(entity, "hbm:weapon.reload.impact", 0.5F, 1F);
			if(timer == 60) entity.world.playSoundAtEntity(entity, "hbm:weapon.reload.revolverClose", 1F, 0.75F);
			if(timer == 70) entity.world.playSoundAtEntity(entity, "hbm:weapon.reload.insertCanister", 1F, 1F);
			if(timer == 85) entity.world.playSoundAtEntity(entity, "hbm:weapon.reload.pressureValve", 1F, 1F);
		}
	};
}

public class XFactoryEnergy {

	public static final ResourceLocation scope_luna = new ResourceLocation(RefStrings.MODID, "textures/misc/scope_amat.png");

	public static BulletConfig energy_tesla;
	public static BulletConfig energy_tesla_overcharge;
	public static BulletConfig energy_tesla_ir;
	public static BulletConfig energy_tesla_ir_sub;

	public static BulletConfig energy_las;
	public static BulletConfig energy_las_overcharge;
	public static BulletConfig energy_las_ir;
	public static BulletConfig energy_emerald;
	public static BulletConfig energy_emerald_overcharge;
	public static BulletConfig energy_emerald_ir;

	public static BiConsumer<EntityBulletBeamBase, RayTraceResult> LAMBDA_LIGHTNING_HIT = (beam, mop) -> {

		Vec3d hitVec = mop.hitVec;
		if(mop.typeOfHit == RayTraceResult.Type.BLOCK) {
			net.minecraft.util.EnumFacing side = mop.sideHit;
			hitVec = hitVec.addVector(side.getFrontOffsetX() * 0.5, side.getFrontOffsetY() * 0.5, side.getFrontOffsetZ() * 0.5);
		}

		ExplosionVNT vnt = new ExplosionVNT(beam.world, hitVec.x, hitVec.y, hitVec.z, 2F, beam.getThrower());
		vnt.setEntityProcessor(new EntityProcessorCrossSmooth(1, beam.damage).setDamageClass(beam.config.dmgClass));
		vnt.setPlayerProcessor(new PlayerProcessorStandard());
		vnt.explode();
		com.hbm.sound.WorldSoundEffects.play(beam.world, hitVec.x, hitVec.y, hitVec.z, "hbm:entity.ufoBlast", 5.0F, 0.9F + beam.world.rand.nextFloat() * 0.2F);
		beam.world.playSoundEffect(hitVec.x, hitVec.y, hitVec.z, "fireworks.blast", 5.0F, 0.5F);

		float yaw = beam.world.rand.nextFloat() * 180F;
		for(int i = 0; i < 3; i++) {
			NBTTagCompound data = new NBTTagCompound();
			data.setString("type", "plasmablast");
			data.setFloat("r", 0.5F);
			data.setFloat("g", 0.5F);
			data.setFloat("b", 1.0F);
			data.setFloat("pitch", -60F + 60F * i);
			data.setFloat("yaw", yaw);
			data.setFloat("scale", 2F);
			PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, hitVec.x, hitVec.y, hitVec.z),
					new TargetPoint(beam.world.provider.getDimension(), hitVec.x, hitVec.y, hitVec.z, 100));
		}

		if(mop.typeOfHit == RayTraceResult.Type.ENTITY) {
			if(mop.entityHit instanceof EntityLivingBase) {
				((EntityLivingBase) mop.entityHit).addPotionEffect(new PotionEffect(Potion.moveSlowdown.id, 60, 9));
				((EntityLivingBase) mop.entityHit).addPotionEffect(new PotionEffect(Potion.digSlowdown.id, 60, 9));
			}
		}
	};

	public static BiConsumer<EntityBulletBeamBase, RayTraceResult> LAMBDA_LIGHTNING_SPLIT = (beam, mop) -> {
		LAMBDA_LIGHTNING_HIT.accept(beam, mop);
		if(mop.typeOfHit != RayTraceResult.Type.ENTITY) return;

		double range = 20;
		List<EntityLivingBase> potentialTargets = beam.world.getEntitiesWithinAABB(EntityLivingBase.class, AxisAlignedBB.getBoundingBox(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z, mop.hitVec.x, mop.hitVec.y, mop.hitVec.z).expand(range, range, range));
		Collections.shuffle(potentialTargets);

		for(EntityLivingBase target : potentialTargets) {
			if(target == beam.thrower) continue;
			if(target == mop.entityHit) continue;

			Vec3d delta = new Vec3d(target.posX - mop.hitVec.x, target.posY + target.height / 2 - mop.hitVec.y, target.posZ - mop.hitVec.z);
			if(delta.length() > 20) continue;
			EntityBulletBeamBase sub = new EntityBulletBeamBase(beam.thrower, energy_tesla_ir_sub, beam.damage);
			sub.setPosition(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z);
			sub.setRotationsFromVector(delta);
			sub.performHitscanExternal(delta.length());
			beam.world.spawnEntityInWorld(sub);
		}
	};

	public static BiConsumer<EntityBulletBeamBase, RayTraceResult> LAMBDA_IR_HIT = (beam, mop) -> {
		BulletConfig.LAMBDA_STANDARD_BEAM_HIT.accept(beam, mop);

		if(mop.typeOfHit == RayTraceResult.Type.ENTITY) {
			if(mop.entityHit instanceof EntityLivingBase) {
				EntityLivingBase living = (EntityLivingBase) mop.entityHit;
				HbmLivingProps props = HbmLivingProps.getData(living);
				if(props.fire < 100) props.fire = 100;
			}
		}

		if(mop.typeOfHit == RayTraceResult.Type.BLOCK) {
			World world = beam.world;
			Block b = world.getBlockState(mop.getBlockPos()).getBlock();
			ForgeDirection dir = ForgeDirection.fromEnumFacing(mop.sideHit);
			if(com.hbm.lib.FacingCompat.isFlammable(b, world, mop.getBlockPos().getX(), mop.getBlockPos().getY(), mop.getBlockPos().getZ(), dir.getOpposite())) {
				int x = mop.getBlockPos().getX() + dir.offsetX;
				int y = mop.getBlockPos().getY() + dir.offsetY;
				int z = mop.getBlockPos().getZ() + dir.offsetZ;
				if(com.hbm.world.WorldBlockState.read(world, x, y, z).getBlock().isAir(world, x, y, z)) {
					world.setBlock(x, y, z, Blocks.fire);
					return;
				}
			}

			EntityFireLingering fire = new EntityFireLingering(beam.world).setArea(2, 1).setDuration(100).setType(EntityFireLingering.TYPE_DIESEL);
			fire.setPosition(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z);
			beam.world.spawnEntityInWorld(fire);
		}
	};

