@Override
	public void update() {

		if(!this.world.isRemote) {

			this.prevConsumption = this.consumption;
			this.consumption = 0;

			int chunkX = this.pos.getX() >> 4;
			int chunkZ = this.pos.getZ() >> 4;

			meltdownTick = false;

			lastTickValid = this.world.getChunkProvider().chunkExists(chunkX, chunkZ) &&
					this.world.getChunkProvider().chunkExists(chunkX + 1, chunkZ + 1) &&
					this.world.getChunkProvider().chunkExists(chunkX + 1, chunkZ - 1) &&
					this.world.getChunkProvider().chunkExists(chunkX - 1, chunkZ + 1) &&
					this.world.getChunkProvider().chunkExists(chunkX - 1, chunkZ - 1);

			if(lastTickValid && heat > 0 && heat >= field) {

				int fill = tanks[0].getFill() + tanks[1].getFill();
				int max = tanks[0].getMaxFill() + tanks[1].getMaxFill();
				int mod = heat * 10;

				int size = Math.max(Math.min(fill * mod / max, 1000), 50);

				boolean canExplode = true;
				Iterator<Entry<ATEntry, Long>> it = EntityNukeExplosionMK3.at.entrySet().iterator();
				while(it.hasNext()) {
					Entry<ATEntry, Long> next = it.next();
					if(next.getValue() < this.world.getTotalWorldTime()) {
						it.remove();
						continue;
					}
					ATEntry entry = next.getKey();
					if(entry.dim != this.world.provider.getDimension())  continue;
					Vec3d vec = new Vec3d(this.pos.getX() + 0.5 - entry.x, this.pos.getY() + 0.5 - entry.y, this.pos.getZ() + 0.5 - entry.z);
					if(vec.length() < 300) {
						canExplode = false;
						break;
					}
				}

				if(canExplode) {

					EntityNukeExplosionMK3 ex = new EntityNukeExplosionMK3(this.world);
					ex.posX = this.pos.getX() + 0.5;
					ex.posY = this.pos.getY() + 0.5;
					ex.posZ = this.pos.getZ() + 0.5;
					ex.destructionRange = size;
					ex.speed = BombConfig.blastSpeed;
					ex.coefficient = 1.0F;
					ex.waste = false;
					this.world.spawnEntityInWorld(ex);

					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "random.explode", 100000.0F, 1.0F);

					EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(this.world, size);
					cloud.posX = this.pos.getX();
					cloud.posY = this.pos.getY();
					cloud.posZ = this.pos.getZ();
					this.world.spawnEntityInWorld(cloud);

				} else {
					meltdownTick = true;
					ChunkRadiationManager.proxy.incrementRad(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), 100);
				}
			}

			if(slots[0] != null && slots[2] != null && slots[0].getItem() instanceof ItemCatalyst && slots[2].getItem() instanceof ItemCatalyst)
				color = calcAvgHex(
						((ItemCatalyst)slots[0].getItem()).getColor(),
						((ItemCatalyst)slots[2].getItem()).getColor()
				);
			else
				color = 0;

			if(heat > 0)
				radiation();

			networkPackNT(250);

			heat = 0;

			if(lastTickValid && field > 0) {
				field -= 1;
			}

			this.markDirty();
		} else {

			//TODO: sick particle effects
		}

	}

@Override
	public void update() {

		if (!this.world.isRemote) {
			for(ForgeDirection dir : ForgeDirection.VALID_DIRECTIONS) this.trySubscribe(this.world, this.pos.getX() + dir.offsetX, this.pos.getY() + dir.offsetY, this.pos.getZ() + dir.offsetZ, dir);
			this.subscribeToAllAround(tank.getTankType(), this);

			watts = MathHelper.clamp(watts, 1, 100);
			long demand = maxPower * watts / 2000;

			beam = 0;

			if(joules > 0 || prev > 0) {

				if(tank.getFill() >= 20) {
					tank.setFill(tank.getFill() - 20);
				} else {
					this.world.setBlock(this.pos.getX(), this.pos.getY(), this.pos.getZ(), Blocks.FLOWING_LAVA);
					return;
				}
			}

			if(isOn) {

				//i.e. 50,000,000 HE = 10,000 SPK
				//1 SPK = 5,000HE

				if(power >= demand) {
					power -= demand;
					long add = watts * 100;
					joules += add;
				}
				prev = joules;

				if(joules > 0) {

					long out = joules * 95 / 100;

					ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());
					for(int i = 1; i <= range; i++) {

						beam = i;

						int x = this.pos.getX() + dir.offsetX * i;
						int y = this.pos.getY() + dir.offsetY * i;
						int z = this.pos.getZ() + dir.offsetZ * i;

						Block block = com.hbm.world.WorldBlockState.read(this.world, x, y, z).getBlock();
						TileEntity te = this.world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

						if(block instanceof ILaserable) { ((ILaserable)block).addEnergy(this.world, x, y, z, out, dir); break; }
						if(te instanceof ILaserable) { ((ILaserable)te).addEnergy(this.world, x, y, z, out, dir); break; }
						if(te instanceof TileEntityCore) { out = ((TileEntityCore)te).burn(out); continue; }

						Block b = com.hbm.world.WorldBlockState.read(this.world, x, y, z).getBlock();

						if(!b.isAir(this.world, x, y, z)) {

							if(b.getDefaultState().getMaterial().isLiquid()) {
								this.world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "random.fizz", 1.0F, 1.0F);
								com.hbm.world.WorldAirRemoval.remove(this.world, x, y, z);
								break;
							}

							float hardness = b.getExplosionResistance(null);
							if(hardness < 6000 && this.world.rand.nextInt(20) == 0) {
								this.world.func_147480_a(x, y, z, false);
							}

							break;
						}
					}


					joules = 0;

					double blx = Math.min(this.pos.getX(), this.pos.getX() + dir.offsetX * beam) + 0.2;
					double bux = Math.max(this.pos.getX(), this.pos.getX() + dir.offsetX * beam) + 0.8;
					double bly = Math.min(this.pos.getY(), this.pos.getY() + dir.offsetY * beam) + 0.2;
					double buy = Math.max(this.pos.getY(), this.pos.getY() + dir.offsetY * beam) + 0.8;
					double blz = Math.min(this.pos.getZ(), this.pos.getZ() + dir.offsetZ * beam) + 0.2;
					double buz = Math.max(this.pos.getZ(), this.pos.getZ() + dir.offsetZ * beam) + 0.8;

					List<Entity> list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(blx, bly, blz, bux, buy, buz));

					for(Entity e : list) {
						e.attackEntityFrom(ModDamageSource.amsCore, 50);
						e.setFire(10);
					}
				}
			} else {
				joules = 0;
				prev = 0;
			}

			this.markDirty();

			this.networkPackNT(250);
		}
	}

