@Override
	public void update() {

		if(!this.world.isRemote) {
			boolean canOperate = false;

			for(int i = 2; i < 6; i++) {
				ForgeDirection dir = ForgeDirection.getOrientation(i);
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

				for(int j = -1; j <= 1; j++) {
					this.sendSmoke(this.pos.getX() + dir.offsetX * 2 + rot.offsetX * j, this.pos.getY(), this.pos.getZ() + dir.offsetZ * 2 + rot.offsetZ * j, dir);
				}
			}

			wasOn = false;

			if(burnTime <= 0) {
				canOperate = breatheAir(0);

				for(int i = 0; i < 2; i++) {
					if(slots[i] != null) {

						int baseTime = getModule().getBurnTime(slots[i]);

						if(baseTime > 0) {
							int fuel = (int) (baseTime * getTimeMult());

							TileEntity below = this.world.getTileEntity(new net.minecraft.util.math.BlockPos(this.pos.getX(), this.pos.getY() - 1, this.pos.getZ()));

							if(below instanceof TileEntityAshpit) {
								TileEntityAshpit ashpit = (TileEntityAshpit) below;
								EnumAshType type = getAshFromFuel(slots[i]);
								if(type == EnumAshType.WOOD) ashpit.ashLevelWood += baseTime;
								if(type == EnumAshType.COAL) ashpit.ashLevelCoal += baseTime;
								if(type == EnumAshType.MISC) ashpit.ashLevelMisc += baseTime;
							}

							this.maxBurnTime = this.burnTime = fuel;
							this.burnHeat = getModule().getBurnHeat(getBaseHeat(), slots[i]);
							slots[i].stackSize--;

							if(slots[i].stackSize == 0) {
								slots[i] = slots[i].getItem().getContainerItem(slots[i]);
							}

							this.wasOn = true;
							break;
						}
					}
				} 
			} else {
				if(this.heatEnergy < getMaxHeat()) {
					// firebox consumes 1mB every 5 ticks, heating oven every tick
					canOperate = breatheAir(this.world.getTotalWorldTime() % (500 / getBaseHeat()) == 0 ? 1 : 0);

					if(canOperate) {
						burnTime--;
						if(this.world.getTotalWorldTime() % 20 == 0) this.pollute(PollutionType.SOOT, PollutionHandler.SOOT_PER_SECOND * 3);
					}
				} else {
					canOperate = breatheAir(0);
				}

				if(canOperate) {
					this.wasOn = true;

					if(this.world.rand.nextInt(15) == 0 && !this.muffled) {
						this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "fire.fire", 1.0F, 0.5F + this.world.rand.nextFloat() * 0.5F);
					}
				}
			}

			if(wasOn) {
				this.heatEnergy = Math.min(this.heatEnergy + this.burnHeat, getMaxHeat());
			} else {
				this.heatEnergy = Math.max(this.heatEnergy - Math.max(this.heatEnergy / 1000, 1), 0);
				if(canOperate) this.burnHeat = 0;
			}

			this.networkPackNT(50);
		} else {
			this.prevDoorAngle = this.doorAngle;
			float swingSpeed = (doorAngle / 10F) + 3;

			if(this.playersUsing > 0) {
				this.doorAngle += swingSpeed;
			} else {
				this.doorAngle -= swingSpeed;
			}

			this.doorAngle = MathHelper.clamp(this.doorAngle, 0F, 135F);

			if(wasOn && this.world.getTotalWorldTime() % 5 == 0) {
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - BlockDummyable.offset);
				double x = this.pos.getX() + 0.5 + dir.offsetX;
				double y = this.pos.getY() + 0.25;
				double z = this.pos.getZ() + 0.5 + dir.offsetZ;
				this.world.spawnParticle("flame", x + this.world.rand.nextDouble() * 0.5 - 0.25, y + this.world.rand.nextDouble() * 0.25, z + this.world.rand.nextDouble() * 0.5 - 0.25, 0, 0, 0);
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(!isSuspended && this.world.getTotalWorldTime() % 20 == 0) {
				if(tank.getFill() > 0) {
					tank.setFill(tank.getFill() - 1);
					this.isOn = true;
				} else {
					this.isOn = false;
				}

				this.subscribeToAllAround(tank.getTankType(), this);
			}

			if(isOn && !isSuspended) {
				Vec3d pivot = new Vec3d(this.pos.getX() + 0.5, this.pos.getY() + 1.75, this.pos.getZ() + 0.5);
				com.hbm.util.Vec3NT upperArm = new com.hbm.util.Vec3NT(0, 0, -4);
				upperArm.rotateAroundXRad((float) Math.toRadians(80 - rotationPitch));
				upperArm.rotateAroundYRad(-(float) Math.toRadians(rotationYaw));
				com.hbm.util.Vec3NT lowerArm = new com.hbm.util.Vec3NT(0, 0, -4);
				lowerArm.rotateAroundXRad((float) -Math.toRadians(80 - rotationPitch));
				lowerArm.rotateAroundYRad(-(float) Math.toRadians(rotationYaw));
				Vec3d armTip = new Vec3d(0, 0, -2);
				armTip = armTip.rotateYaw(-(float) Math.toRadians(rotationYaw));

				double cX = pivot.x + upperArm.x + lowerArm.x + armTip.x;
				double cY = pivot.y;
				double cZ = pivot.z + upperArm.z + lowerArm.z + armTip.z;

				List<EntityLivingBase> affected = this.world.getEntitiesWithinAABB(EntityLivingBase.class, AxisAlignedBB.getBoundingBox(cX - 1, cY - 0.25, cZ - 1, cX + 1, cY + 0.25, cZ + 1));

				for(EntityLivingBase e : affected) {
					if(e.isEntityAlive() && e.attackEntityFrom(ModDamageSource.turbofan, 100)) {
						this.world.playSoundEffect(e.posX, e.posY, e.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
						int count = Math.min((int)Math.ceil(e.getMaxHealth() / 4), 250);
						NBTTagCompound data = new NBTTagCompound();
						data.setString("type", "vanillaburst");
						data.setInteger("count", count * 4);
						data.setDouble("motion", 0.1D);
						data.setString("mode", "blockdust");
						data.setInteger("block", Block.getIdFromBlock(Blocks.REDSTONE_BLOCK));
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, e.posX, e.posY + e.height * 0.5, e.posZ), new TargetPoint(e.dimension, e.posX, e.posY, e.posZ, 50));
					}
				}

				if(state == 0) {

					this.rotationYaw += 1;

					if(this.rotationYaw >= 360) {
						this.rotationYaw -= 360;
					}

					if(forceSkip > 0) {
						forceSkip--;
					} else {
						final double CUT_ANGLE = Math.toRadians(5);
						double rotationYawRads = Math.toRadians((rotationYaw + 270) % 360);

						outer:
						for(int dx = -MAX_DIST; dx <= MAX_DIST; dx++) {
							for(int dz = -MAX_DIST; dz <= MAX_DIST; dz++) {
								int sqrDst = dx * dx + dz * dz;

								if(sqrDst <= MIN_DIST * MIN_DIST || sqrDst > MAX_DIST * MAX_DIST)
									continue;

								double angle = Math.atan2(dz, dx);
								double relAngle = Math.abs(angle - rotationYawRads);
								relAngle = Math.abs((relAngle + Math.PI) % (2 * Math.PI) - Math.PI);

								if(relAngle > CUT_ANGLE) continue;

								int x = this.pos.getX() + dx;
								int y = this.pos.getY() + 1;
								int z = this.pos.getZ() + dz;

								Block b = com.hbm.world.WorldBlockState.read(this.world, x, y, z).getBlock();
								if(!(b.getDefaultState().getMaterial() == Material.wood || b.getDefaultState().getMaterial() == Material.LEAVES || b.getDefaultState().getMaterial() == Material.PLANTS))
									continue;

								int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(this.world, x, y, z) );
								if(shouldIgnore(this.world, x, y, z, b, meta)) continue;

								state = 1;
								break outer;
							}
						}
					}
				}

				int hitY = (int) Math.floor(cY);
				int hitX0 = (int) Math.floor(cX - 0.5);
				int hitZ0 = (int) Math.floor(cZ - 0.5);
				int hitX1 = (int) Math.floor(cX + 0.5);
				int hitZ1 = (int) Math.floor(cZ + 0.5);

				this.tryInteract(hitX0, hitY, hitZ0);
				this.tryInteract(hitX1, hitY, hitZ0);
				this.tryInteract(hitX0, hitY, hitZ1);
				this.tryInteract(hitX1, hitY, hitZ1);

				if(state == 1) {
					this.rotationPitch += 2;

					if(this.rotationPitch > 80) {
						this.rotationPitch = 80;
						state = 2;
					}
				}

				if(state == 2) {
					this.rotationPitch -= 2;

					if(this.rotationPitch <= 0) {
						this.rotationPitch = 0;
						state = 0;
					}
				}
			}

			networkPackNT(100);
		} else {

			this.lastSpin = this.spin;

			if(isOn && !isSuspended) {
				this.spin += 15F;

				Vec3d vec = new Vec3d(0.625, 0, 1.625);
				vec = vec.rotateYaw(-(float) Math.toRadians(rotationYaw));

				this.world.spawnParticle("smoke", this.pos.getX() + 0.5 + vec.x, this.pos.getY() + 2.0625, this.pos.getZ() + 0.5 + vec.z, 0, 0, 0);
			}

			if(this.spin >= 360F) {
				this.spin -= 360F;
				this.lastSpin -= 360F;
			}

			this.prevRotationYaw = this.rotationYaw;
			this.prevRotationPitch = this.rotationPitch;

			if(this.turnProgress > 0) {
				double d0 = MathHelper.wrapDegrees(this.syncYaw - (double) this.rotationYaw);
				double d1 = MathHelper.wrapDegrees(this.syncPitch - (double) this.rotationPitch);
				this.rotationYaw = (float) ((double) this.rotationYaw + d0 / (double) this.turnProgress);
				this.rotationPitch = (float) ((double) this.rotationPitch + d1 / (double) this.turnProgress);
				--this.turnProgress;
			} else {
				this.rotationYaw = this.syncYaw;
				this.rotationPitch = this.syncPitch;
			}
		}
	}

@Override
	public void update() {

		ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - 10);

		if(!this.world.isRemote) {

			this.power = Library.chargeTEFromItems(slots, 0, power, maxPower);

			tanks[0].setType(1, slots);
			FluidType conversion = this.getFluidOutput(tanks[0].getTankType());
			if(conversion != null) tanks[1].setTankType(conversion);

			for(DirPos pos : getConPos()) {
				this.trySubscribe(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.trySubscribe(tanks[0].getTankType(), this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				if(tanks[1].getFill() > 0) this.sendFluid(tanks[1], this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
			}

			this.processing = false;

			upgradeManager.checkSlots(this, slots, 9, 10);
			int speed = upgradeManager.getLevel(UpgradeType.SPEED);
			int efficiency = upgradeManager.getLevel(UpgradeType.EFFECT);

			this.consumption = this.consumptionBase + (this.consumptionBase * speed) / 2 + (this.consumptionBase * efficiency);

			if(canSlop()) {
				this.power -= this.consumption;
				this.progress += 1F / (600 - speed * 150);
				this.processing = true;
				boolean markDirty = false;

				while(progress >= 1F && canSlop()) {
					progress -= 1F;

					fromBody = ItemBedrockOreBase.getOreBody(slots[2]);

					for(CelestialBedrockOreType type : CelestialBedrockOre.get(fromBody).types) {
						ores[type.index] += (ItemBedrockOreBase.getOreAmount(slots[2], type) * (1D + efficiency * 0.1));
					}

					this.decrStackSize(2, 1);
					this.tanks[0].setFill(this.tanks[0].getFill() - waterUsed);
					this.tanks[1].setFill(this.tanks[1].getFill() + waterUsed);
					markDirty = true;
				}

				if(markDirty) this.markDirty();

				List<Entity> entities = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 0.5, this.pos.getY() + 1, this.pos.getZ() - 0.5, this.pos.getX() + 1.5, this.pos.getY() + 3, this.pos.getZ() + 1.5).offset(dir.offsetX, 0, dir.offsetZ));

				for(Entity e : entities) {
					e.attackEntityFrom(ModDamageSource.turbofan, 1000F);

					if(!e.isEntityAlive() && e instanceof EntityLivingBase) {
						NBTTagCompound vdat = new NBTTagCompound();
						vdat.setString("type", "giblets");
						vdat.setInteger("ent", e.getEntityId());
						vdat.setInteger("cDiv", 5);
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, e.posX, e.posY + e.height * 0.5, e.posZ), new TargetPoint(e.dimension, e.posX, e.posY + e.height * 0.5, e.posZ, 150));

						this.world.playSoundEffect(e.posX, e.posY, e.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
					}
				}

			} else {
				this.progress = 0;
			}

			for(CelestialBedrockOreType type : CelestialBedrockOre.getAllTypes()) {
				ItemStack output = ItemBedrockOreNew.make(BedrockOreGrade.BASE, type);
				outer: while(ores[type.index] >= 1) {
					for(int i = 3; i <= 8; i++) if(slots[i] != null && slots[i].getItem() == output.getItem() && slots[i].getItemDamage() == output.getItemDamage() && slots[i].stackSize < output.getMaxStackSize()) {
						slots[i].stackSize++; ores[type.index] -= 1F; continue outer;
					}
					for(int i = 3; i <= 8; i++) if(slots[i] == null) {
						slots[i] = output; ores[type.index] -= 1F; continue outer;
					}
					break outer;
				}
			}

			this.networkPackNT(150);

		} else {

			this.prevSlider = this.slider;
			this.prevBucket = this.bucket;
			this.prevBlades = this.blades;
			this.prevFan = this.fan;

			if(this.processing) {

				this.blades += 15F;
				this.fan += 35F;

				if(blades >= 360) {
					blades -= 360;
					prevBlades -= 360;
				}

				if(fan >= 360) {
					fan -= 360;
					prevFan -= 360;
				}

				if(animation == animation.DUMPING && MainRegistry.proxy.me().getDistance(this.pos.getX() + 0.5, this.pos.getY() + 4, this.pos.getZ() + 0.5) <= 50) {
					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "vanillaExt");
					data.setString("mode", "blockdust");
					data.setInteger("block", Block.getIdFromBlock(Blocks.IRON_BLOCK));
					data.setDouble("posX", this.pos.getX() + 0.5 + dir.offsetX + this.world.rand.nextGaussian() * 0.25);
					data.setDouble("posY", this.pos.getY() + 4.25);
					data.setDouble("posZ", this.pos.getZ() + 0.5 + dir.offsetZ + this.world.rand.nextGaussian() * 0.25);
					data.setDouble("mY", -0.2D);
					MainRegistry.proxy.effectNT(data);
				}

				if(delay > 0) {
					delay--;
					return;
				}

				switch(animation) {
				case LOWERING:
					this.bucket += 1F/40F;
					if(bucket >= 1F) {
						bucket = 1F;
						animation = SlopperAnimation.LIFTING;
						delay = 20;
					}
					break;
				case LIFTING:
					this.bucket -= 1F/40F;
					if(bucket <= 0) {
						bucket = 0F;
						animation = SlopperAnimation.MOVE_SHREDDER;
						delay = 10;
					}
					break;
				case MOVE_SHREDDER:
					this.slider += 1/50F;
					if(slider >= 1F) {
						slider = 1F;
						animation = SlopperAnimation.DUMPING;
						delay = 60;
					}
					break;
				case DUMPING:
					animation = SlopperAnimation.MOVE_BUCKET;
					break;
				case MOVE_BUCKET:
					this.slider -= 1/50F;
					if(slider <= 0F) {
						animation = SlopperAnimation.LOWERING;
						delay = 10;
					}
					break;
				}
			}
		}
	}

@Override
	public void update() {
		boolean flag1 = false;

		if(!this.world.isRemote) {

			this.updateConnections();

			if(this.progress == 0) this.soundCycle = 0;

			if(hasPower() && canProcess()) {
				progress++;

				power -= 5;

				if(this.progress == TileEntityMachineShredder.processingSpeed) {
					for(int i = 27; i <= 28; i++)
						if(slots[i].getMaxDamage() > 0)
							this.slots[i].setItemDamage(this.slots[i].getItemDamage() + 1);

					this.progress = 0;
					this.processItem();
					flag1 = true;
				}
				if(soundCycle == 0)
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "minecart.base", getVolume(1.0F), 0.75F);
				soundCycle++;

				if(soundCycle >= 50)
					soundCycle = 0;
			} else {
				progress = 0;
			}

			boolean trigger = true;

			if(hasPower() && canProcess() && this.progress == 0) {
				trigger = false;
			}

			if(trigger) {
				flag1 = true;
			}

			power = Library.chargeTEFromItems(slots, 29, power, maxPower);

			networkPackNT(50);
		}

		if(flag1) {
			this.markDirty();
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			this.output = 0;
			this.consumption = 0;

			//meta below 12 means that it's an old multiblock configuration
			if(this.getBlockMetadata() < 12) {
				//get old direction
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());
				//remove tile from the world to prevent inventory dropping
				this.world.removeTileEntity(this.pos.getX(), this.pos.getY(), this.pos.getZ());
				//use fillspace to create a new multiblock configuration
				this.world.setBlock(this.pos.getX(), this.pos.getY(), this.pos.getZ(), ModBlocks.machine_turbofan, dir.ordinal() + 10, 3);
				MultiblockHandlerXR.fillSpace(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), ((BlockDummyable) ModBlocks.machine_turbofan).getDimensions(), ModBlocks.machine_turbofan, dir);
				//restore connections
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() + dir.offsetX, this.pos.getY(), this.pos.getZ() + dir.offsetZ);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() + dir.offsetX - rot.offsetX, this.pos.getY(), this.pos.getZ() + dir.offsetZ - rot.offsetZ);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() - dir.offsetX, this.pos.getY(), this.pos.getZ() - dir.offsetZ);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() - dir.offsetX - rot.offsetX, this.pos.getY(), this.pos.getZ() - dir.offsetZ - rot.offsetZ);
				//load the tile data to restore the old values
				NBTTagCompound data = new NBTTagCompound();
				this.writeToNBT(data);
				this.world.getTileEntity(new net.minecraft.util.math.BlockPos(this.pos.getX(), this.pos.getY(), this.pos.getZ())).readFromNBT(data);
				return;
			}

			tank.setType(4, slots);
			tank.loadTank(0, 1, slots);
			blood.setTankType(Fluids.BLOOD);

			this.wasOn = false;

			upgradeManager.checkSlots(this, slots, 2, 2);
			this.afterburner = upgradeManager.getLevel(UpgradeType.AFTERBURN);

			if(slots[2] != null && slots[2].getItem() == ModItems.flame_pony)
				this.afterburner = 100;

			long burnValue = 0;
			int amount = 1 + this.afterburner;

			boolean redstone = false;

			for(DirPos pos : getConPos()) {
				if(this.world.isBlockIndirectlyGettingPowered(pos.getX(), pos.getY(), pos.getZ())) {
					redstone = true;
					break;
				}
			}

			int amountToBurn = 0;

			if(!redstone) {

				if(tank.getTankType().hasTrait(FT_Combustible.class) && tank.getTankType().getTrait(FT_Combustible.class).getGrade() == FuelGrade.AERO) {
					burnValue = tank.getTankType().getTrait(FT_Combustible.class).getCombustionEnergy() / 1_000;
				}

				amountToBurn = Math.min(amount, this.tank.getFill());
				if(amountToBurn > 0 && !breatheAir(amountToBurn)) amountToBurn = 0;

				if(amountToBurn > 0) {
					this.wasOn = true;
					this.tank.setFill(this.tank.getFill() - amountToBurn);
					this.output = (int) (burnValue * amountToBurn * (1 + Math.min(this.afterburner / 3D, 4)));
					this.power += this.output;
					this.consumption = amountToBurn;

					if(this.world.getTotalWorldTime() % 20 == 0) super.pollute(tank.getTankType(), FluidTrait.FluidReleaseType.BURN, amountToBurn * 5);;
				}
			}

			power = Library.chargeItemsFromTE(slots, 3, power, power);

			for(DirPos pos : getConPos()) {
				this.tryProvide(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.trySubscribe(tank.getTankType(), this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				if(this.blood.getFill() > 0) this.sendFluid(blood, this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.sendSmoke(pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
			}

			if(burnValue > 0 && amountToBurn > 0) {

				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - 10).getRotation(ForgeDirection.UP);
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

				if(this.afterburner > 0) {

					for(int i = 0; i < 2; i++) {
						double speed = 2 + this.world.rand.nextDouble() * 3;
						double deviation = this.world.rand.nextGaussian() * 0.2;
						NBTTagCompound data = new NBTTagCompound();
						data.setString("type", "gasfire");
						data.setDouble("mX", -dir.offsetX * speed + deviation);
						data.setDouble("mZ", -dir.offsetZ * speed + deviation);
						data.setFloat("scale", 8F);
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, this.pos.getX() + 0.5F - dir.offsetX * (3 - i), this.pos.getY() + 1.5F, this.pos.getZ() + 0.5F - dir.offsetZ * (3 - i)), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));
					}

					/*if(this.afterburner > 90 && worldObj.rand.nextInt(60) == 0) {
						worldObj.newExplosion(null, xCoord + 0.5 + dir.offsetX * 3.5, yCoord + 0.5, zCoord + 0.5 + dir.offsetZ * 3.5, 3F, false, false);
					}*/

					if(this.afterburner > 90 && this.world.rand.nextInt(30) == 0) {
						com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX() + 0.5, this.pos.getY() + 1.5, this.pos.getZ() + 0.5, "hbm:block.damage", 3.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
					}

					if(this.afterburner > 90) {
						NBTTagCompound data = new NBTTagCompound();
						data.setString("type", "gasfire");
						data.setDouble("mY", 0.1 * this.world.rand.nextDouble());
						data.setFloat("scale", 4F);
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data,
								this.pos.getX() + 0.5F + dir.offsetX * (this.world.rand.nextDouble() * 4 - 2) + rot.offsetX * (this.world.rand.nextDouble() * 2 - 1),
								this.pos.getY() + 1F + this.world.rand.nextDouble() * 2,
								this.pos.getZ() + 0.5F - dir.offsetZ * (this.world.rand.nextDouble() * 4 - 2) + rot.offsetZ * (this.world.rand.nextDouble() * 2 - 1)
								), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));
					}
				}

				double minX = this.pos.getX() + 0.5 - dir.offsetX * 3.5 - rot.offsetX * 1.5;
				double maxX = this.pos.getX() + 0.5 - dir.offsetX * 19.5 + rot.offsetX * 1.5;
				double minZ = this.pos.getZ() + 0.5 - dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				double maxZ = this.pos.getZ() + 0.5 - dir.offsetZ * 19.5 + rot.offsetZ * 1.5;

				List<Entity> list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {

					if(this.afterburner > 0) {
						e.setFire(5);
						e.attackEntityFrom(DamageSource.onFire, 5F);
					}
					e.motionX -= dir.offsetX * 0.2;
					e.motionZ -= dir.offsetZ * 0.2;
				}

				minX = this.pos.getX() + 0.5 + dir.offsetX * 3.5 - rot.offsetX * 1.5;
				maxX = this.pos.getX() + 0.5 + dir.offsetX * 8.5 + rot.offsetX * 1.5;
				minZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				maxZ = this.pos.getZ() + 0.5 + dir.offsetZ * 8.5 + rot.offsetZ * 1.5;

				list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {
					e.motionX -= dir.offsetX * 0.2;
					e.motionZ -= dir.offsetZ * 0.2;
				}

				minX = this.pos.getX() + 0.5 + dir.offsetX * 3.5 - rot.offsetX * 1.5;
				maxX = this.pos.getX() + 0.5 + dir.offsetX * 3.75 + rot.offsetX * 1.5;
				minZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				maxZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.75 + rot.offsetZ * 1.5;

				list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {
					e.attackEntityFrom(ModDamageSource.turbofan, 1000);
					e.setInWeb();

					if(!e.isEntityAlive() && e instanceof EntityLivingBase) {
						NBTTagCompound vdat = new NBTTagCompound();
						vdat.setString("type", "giblets");
						vdat.setInteger("ent", e.getEntityId());
						vdat.setInteger("cDiv", 5);
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, e.posX, e.posY + e.height * 0.5, e.posZ), new TargetPoint(e.dimension, e.posX, e.posY + e.height * 0.5, e.posZ, 150));

						this.world.playSoundEffect(e.posX, e.posY, e.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);

						blood.setFill(blood.getFill() + 50);
						if(blood.getFill() > blood.getMaxFill()) {
							blood.setFill(blood.getMaxFill());
						}
						this.showBlood = true;
					}
				}
			}

			if(this.power > this.maxPower) {
				this.power = this.maxPower;
			}

			this.networkPackNT(150);

		} else {

			this.lastSpin = this.spin;

			if(wasOn) {
				if(this.momentum < 100F)
					this.momentum++;
			} else {
				if(this.momentum > 0)
					this.momentum--;
			}

			this.spin += momentum / 2;

			if(this.spin >= 360) {
				this.spin -= 360F;
				this.lastSpin -= 360F;
			}

			if(momentum > 0) {

				if(audio == null) {
					audio = createAudioLoop();
					audio.startSound();
				} else if(!audio.isPlaying()) {
					audio = rebootAudio(audio);
				}

				audio.keepAlive();
				audio.updateVolume(getVolume(momentum / 50F));
				audio.updatePitch(momentum / 200F + 0.5F + this.afterburner * 0.16F);

			} else {

				if(audio != null) {
					audio.stopSound();
					audio = null;
				}
			}

			/*
			 * All movement related stuff has to be repeated on the client, but only for the client's player
			 * Otherwise this could lead to desync since the motion is never sent form the server
			 */
			if(wasOn && !MainRegistry.proxy.me().capabilities.isCreativeMode) {
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - 10).getRotation(ForgeDirection.UP);
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

				double minX = this.pos.getX() + 0.5 - dir.offsetX * 3.5 - rot.offsetX * 1.5;
