			}
		}
	}

@SuppressWarnings("unchecked")
	@Override
	public void update() {
		ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata()).getOpposite();
		ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

		if(!this.world.isRemote) {
			trySubscribe(tank.getTankType(), this.world, this.pos.getX() + dir.offsetX, this.pos.getY(), this.pos.getZ() + dir.offsetZ, dir);

			isOperating = false;

			List<EntityPlayer> players = this.world.getEntitiesWithinAABB(EntityPlayer.class, AxisAlignedBB.getBoundingBox(this.pos.getX() + 0.5, this.pos.getY(), this.pos.getZ() + 0.5, this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5).expand(0.5, 0.0, 0.5));

			for(EntityPlayer player : players) {
				for(int i = 0; i < 5; i++) {

					ItemStack stack = player.getEquipmentInSlot(i);
					if(stack == null) continue;

					if(fillFillable(stack)) {
						isOperating = true;
					}

					if(stack.getItem() instanceof ItemArmor && ArmorModHandler.hasMods(stack)) {
						for(ItemStack mod : ArmorModHandler.pryMods(stack)) {
							if(mod == null) continue;

							if(fillFillable(mod)) {
								ArmorModHandler.applyMod(stack, mod);
								isOperating = true;
							}
						}
					}
				}
			}

			if(isOperating) {
				if(operatingTime % 20 == 0)
					this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5, "random.fizz", 0.2F, 0.5F);

				operatingTime++;
			} else {
				operatingTime = 0;
			}

			networkPackNT(150);
		} else {
			if(isOperating) {
				Random rand = this.world.rand;

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "fluidfill");
				data.setInteger("color", tank.getTankType().getColor());
				data.setDouble("posX", this.pos.getX() + 0.5 + rand.nextDouble() * 0.0625 + dir.offsetX * 0.5 + rot.offsetX * 0.25);
				data.setDouble("posZ", this.pos.getZ() + 0.5 + rand.nextDouble() * 0.0625 + dir.offsetZ * 0.5 + rot.offsetZ * 0.25);
				data.setDouble("posY", this.pos.getY() + 0.375);
				data.setDouble("mX", -dir.offsetX + rand.nextGaussian() * 0.1);
				data.setDouble("mZ", -dir.offsetZ + rand.nextGaussian() * 0.1);
				data.setDouble("mY", 0D);

				MainRegistry.proxy.effectNT(data);
			}

			prevFillLevel = fillLevel;

			double targetFill = (double)tank.getFill() / (double)tank.getMaxFill();
			fillLevel = BobMathUtil.interp(fillLevel, targetFill, targetFill > fillLevel || !isOperating ? 0.1F : 0.01F);
		}


	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(hasBlade) {
				tryPullHeat();

				if(warnCooldown > 0)
					warnCooldown--;

				if(heat >= 100) {

					ItemStack result = this.getOutput(slots[0]);

					if(result != null) {
						progress += heat / 10;

						if(progress >= processingTime) {
							progress = 0;
							slots[0] = null;
							slots[1] = result;

							float sawdustChance = sawdustChance(result);

							if(sawdustChance > 0) {
								if(this.world.rand.nextFloat() < sawdustChance) {
									slots[2] = new ItemStack(ModItems.powder_sawdust);
								}
							}

							this.markDirty();
						}

					} else {
						this.progress = 0;
					}

					AxisAlignedBB aabb = new AxisAlignedBB(-1D, 0.375D, -1D, -0.875, 2.375D, 1D);
					aabb = BlockDummyable.getAABBRotationOffset(aabb, this.pos.getX() + 0.5, this.pos.getY(), this.pos.getZ() + 0.5, ForgeDirection.getOrientation(this.getBlockMetadata() - BlockDummyable.offset).getRotation(ForgeDirection.UP));
					for(Object o : this.world.getEntitiesWithinAABB(EntityLivingBase.class, aabb)) {
						EntityLivingBase e = (EntityLivingBase) o;
						if(e.isEntityAlive() && e.attackEntityFrom(ModDamageSource.turbofan, 100)) {
							this.world.playSoundEffect(e.posX, e.posY, e.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
							int count = Math.min((int)Math.ceil(e.getMaxHealth() / 4), 250);
							NBTTagCompound data = new NBTTagCompound();
							data.setString("type", "vanillaburst");
							data.setInteger("count", count * 4);
							data.setDouble("motion", 0.1D);
							data.setString("mode", "blockdust");
							data.setInteger("block", Block.getIdFromBlock(Blocks.REDSTONE_BLOCK));
							PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, e.posX, e.posY + e.height * 0.5, e.posZ), new TargetPoint(e.dimension, e.posX, e.posY, e.posZ, 50));
						}
					}

				} else {
					this.progress = 0;
				}

				if(heat > 300) {

					this.overspeed++;

					if(overspeed > 60 && warnCooldown == 0) {
						warnCooldown = 100;
						this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5, "hbm:block.warnOverspeed", 2.0F, 1.0F);
					}

					if(overspeed > 300) {
						this.hasBlade = false;
						this.world.newExplosion(null, this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5, 5F, false, false);

						int orientation = this.getBlockMetadata() - BlockDummyable.offset;
						ForgeDirection dir = ForgeDirection.getOrientation(orientation);
						EntitySawblade cog = new EntitySawblade(this.world, this.pos.getX() + 0.5 + dir.offsetX, this.pos.getY() + 1, this.pos.getZ() + 0.5 + dir.offsetZ).setOrientation(orientation);
						ForgeDirection rot = dir.getRotation(ForgeDirection.DOWN);

						cog.motionX = rot.offsetX;
						cog.motionY = 1 + (heat - 100) * 0.0001D;
						cog.motionZ = rot.offsetZ;
						this.world.spawnEntityInWorld(cog);

						this.markDirty();
					}

				} else {
					this.overspeed = 0;
				}
			} else {
				this.overspeed = 0;
				this.warnCooldown = 0;
			}

			networkPackNT(150);

			this.heat = 0;

		} else {

			float momentum = heat * 25F / ((float) 300);

