@Override
	public void update() {

		if(!this.world.isRemote) {

			this.sendingChar = ' ';

			if(this.isSending && this.txChannel.isEmpty()) this.isSending = false;

			if(this.isSending) {

				if(sendingWait > 0) {
					sendingWait--;
				} else {

					String line = txBuffer[sendingLine];

					if(line.length() > sendingIndex) {
						char c = line.charAt(sendingIndex);
						sendingIndex++;
						if(c == pause) {
							sendingWait = 20;
						} else {
							RTTYSystem.broadcast(this.world, this.txChannel, c);
							this.sendingChar = c;
						}
					} else {

						if(sendingLine >= 4) {
							this.isSending = false;
							RTTYSystem.broadcast(this.world, this.txChannel, eot);
							this.sendingLine = 0;
							this.sendingIndex = 0;
						} else {
							RTTYSystem.broadcast(this.world, this.txChannel, eol);
							this.sendingLine++;
							this.sendingIndex = 0;
						}
					}
				}
			}

			if(!this.rxChannel.isEmpty()) {
				RTTYChannel chan = RTTYSystem.listen(this.world, this.rxChannel);

				if(chan != null && chan.signal instanceof Character && (chan.timeStamp > this.world.getTotalWorldTime() - 2 && chan.timeStamp != -1)) {
					char c = (char) chan.signal;

					if(this.deleteOnReceive) {
						this.deleteOnReceive = false;
						for(int i = 0; i < 5; i++) this.rxBuffer[i] = "";
						this.writingLine = 0;
					}

					if(c == eot) {
						if(this.printAfterRx) {
							this.printAfterRx = false;
							this.print();
						}
						this.deleteOnReceive = true;
					} else if(c == eol) {
						if(this.writingLine < 4) this.writingLine++;
						this.markDirty();
					} else if(c == bell) {
						this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "random.orb", 2F, 0.5F);
					} else if(c == print) {
						this.printAfterRx = true;
					} else if(c == clear) {
						for(int i = 0; i < 5; i++) this.rxBuffer[i] = "";
						this.writingLine = 0;
					} else {
						this.rxBuffer[this.writingLine] += c;
						this.markDirty();
					}
				}
			}

			networkPackNT(16);
		}
	}

@Override
	public void updateFiringTick() {

		long demand = this.getConsumption() * 10;

		if(this.target != null && this.getPower() >= demand) {

			if(_5g && target instanceof EntityPlayer) {
				EntityPlayer living = (EntityPlayer) target;
				living.addPotionEffect(new PotionEffect(HbmPotion.death.id, 30 * 60 * 20, 0, true));
			} else {
				EntityDamageUtil.attackEntityFromIgnoreIFrame(this.target, ModDamageSource.microwave, (this.blackLevel * 10 + this.redLevel + 1F) * 0.25F);
			}

			if(pinkLevel > 0)
				this.target.setFire(this.pinkLevel * 3);

			if(!this.target.isEntityAlive() && this.target instanceof EntityLivingBase) {
				NBTTagCompound vdat = new NBTTagCompound();
				vdat.setString("type", "giblets");
				vdat.setInteger("ent", this.target.getEntityId());
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, this.target.posX, this.target.posY + this.target.height * 0.5, this.target.posZ), new TargetPoint(this.target.dimension, this.target.posX, this.target.posY + this.target.height * 0.5, this.target.posZ, 150));

				if(this.screm)
					com.hbm.sound.WorldSoundEffects.play(this.world, this.target.posX, this.target.posY, this.target.posZ, "hbm:block.screm", 20.0F, 1.0F);
				else
					this.world.playSoundEffect(this.target.posX, this.target.posY, this.target.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
			}

			this.power -= demand;

			this.shot = true;
			this.networkPackNT(250);
			this.shot = false;
		}
	}

